// TypeScript Version: 4.1

/// <reference types="@stdlib/types"/>

import { IterableIterator } from '@stdlib/types/iter';

/**
 * Checks whether an element in a queue passes a test.
 *
 * @param value - current queue element
 * @param index - current queue element index
 * @param q - queue on which the method was called
 * @returns boolean indicating whether an element in a queue passes a test
 */
type NullaryPredicate<U> = ( this: U ) => boolean;

/**
 * Checks whether an element in a queue passes a test.
 *
 * @param value - current queue element
 * @returns boolean indicating whether an element in a queue passes a test
 */
type UnaryPredicate<T, U> = ( this: U, value: T ) => boolean;

/**
 * Checks whether an element in a queue passes a test.
 *
 * @param value - current queue element
 * @param index - current queue element index
 * @returns boolean indicating whether an element in a queue passes a test
 */
type BinaryPredicate<T, U> = ( this: U, value: T, index: number ) => boolean;

/**
 * Checks whether an element in a queue passes a test.
 *
 * @param value - current queue element
 * @param index - current queue element index
 * @param q - queue on which the method was called
 * @returns boolean indicating whether an element in a queue passes a test
 */
type TernaryPredicate<T, U> = ( this: U, value: T, index: number, q: FIFO<T> ) => boolean;

/**
* Checks whether an element in an queue passes a test.
*
* @param value - current queue element
* @param index - current queue element index
* @param q - queue on which the method was called
* @returns boolean indicating whether an element in a queue passes a test
*/
type Predicate<T, U> = NullaryPredicate<U> | UnaryPredicate<T, U> | BinaryPredicate<T, U> | TernaryPredicate<T, U>;

/**
* Serialized FIFO queue.
*
* @template T - queue element type
*/
interface SerializedFIFO<T> {
	type: string;
	data: Array<T>;
}

/**
* First-in-first-out (FIFO) queue.
*
* @template T - queue element type
*/
declare class FIFO<T = unknown> {
	/**
	* First-in-first-out queue constructor.
	*
	* @returns FIFO queue instance
	*
	* @example
	* var FIFO = require( '@stdlib/dstructs/fifo' );
	*
	* var queue = new FIFO();
	*
	* // Add values to the queue:
	* queue.push( 'foo' ).push( 'bar' );
	*
	* // Remove the first value:
	* var v = queue.pop();
	* // returns 'foo'
	*
	* // Add a new value to the queue:
	* queue.push( 'beep' );
	*
	* // Remove the "oldest" queue value:
	* v = queue.pop();
	* // returns 'bar'
	*/
	constructor();

	/**
	* Clears the queue.
	*
	* @returns queue instance
	*
	* @example
	* var FIFO = require( '@stdlib/dstructs/fifo' );
	*
	* var queue = new FIFO();
	*
	* // Add values to the queue:
	* queue.push( 'foo' ).push( 'bar' );
	*
	* // Peek at the first value:
	* var v = queue.first();
	* // returns 'foo'
	*
	* // Examine the queue length:
	* var len = queue.length;
	* // returns 2
	*
	* // Clear all queue items:
	* queue.clear();
	*
	* // Peek at the first value:
	* v = queue.first();
	* // returns undefined
	*
	* // Examine the queue length:
	* len = queue.length;
	* // returns 0
	*/
	clear(): FIFO;

	/**
	* Tests whether all elements in a queue pass a test implemented by a predicate function.
	*
	* ## Notes
	*
	* -   If the queue is empty, the method returns `true`.
	*
	* @param predicate - predicate function to test queue elements
	* @param thisArg - execution context for the predicate function
	* @throws first argument must be a function
	* @returns boolean indicating whether all elements pass a test
	*
	* @example
	* var FIFO = require( '@stdlib/dstructs/fifo' );
	*
	* function predicate( v ) {
	*     return v > 0;
	* }
	*
	* var queue = new FIFO();
	*
	* queue.push( 1 ).push( 2 ).push( 3 );
	*
	* var bool = queue.every( predicate );
	* // returns true
	*/
	every<U = unknown>( predicate: Predicate<T, U>, thisArg?: U ): boolean;

	/**
	* Returns the "oldest" queue value (i.e., the value which is "first-out").
	*
	* @returns "oldest" queue value
	*
	* @example
	* var FIFO = require( '@stdlib/dstructs/fifo' );
	*
	* var queue = new FIFO();
	*
	* // Add values to the queue:
	* queue.push( 'foo' ).push( 'bar' );
	*
	* // Peek at the first value:
	* var v = queue.first();
	* // returns 'foo'
	*/
	first(): T | void;

	/**
	* Returns a queue element located at a nonnegative integer position (index) `i`.
	*
	* @param i - element index
	* @throws index argument must be a nonnegative integer
	* @returns queue element
	*
	* @example
	* var FIFO = require( '@stdlib/dstructs/fifo' );
	*
	* var queue = new FIFO();
	*
	* queue.push( 'foo' ).push( 'bar' );
	*
	* var v = queue.get( 0 );
	* // returns 'foo'
	*
	* v = queue.get( 1 );
	* // returns 'bar'
	*/
	get( i: number ): T | void;

	/**
	* Returns an iterator for iterating over a queue.
	*
	* ## Notes
	*
	* -   In order to prevent confusion arising from queue mutation during iteration, a returned iterator **always** iterates over a queue "snapshot", which is defined as the list of queue elements at the time of this method's invocation.
	*
	* @returns iterator
	*
	* @example
	* var FIFO = require( '@stdlib/dstructs/fifo' );
	*
	* var queue = new FIFO();
	*
	* // Add values to the queue:
	* queue.push( 'foo' ).push( 'bar' );
	*
	* // Create an iterator:
	* var it = queue.iterator();
	*
	* // Iterate over the queue...
	* var v = it.next().value;
	* // returns 'foo'
	*
	* v = it.next().value;
	* // returns 'bar'
	*
	* var bool = it.next().done;
	* // returns true
	*/
	iterator(): IterableIterator;

	/**
	* Returns the "newest" queue value (i.e., the value which is currently "last-out").
	*
	* @returns "newest" queue value
	*
	* @example
	* var FIFO = require( '@stdlib/dstructs/fifo' );
	*
	* var queue = new FIFO();
	*
	* // Add values to the queue:
	* queue.push( 'foo' ).push( 'bar' );
	*
	* // Peek at the last value:
	* var v = queue.last();
	* // returns 'bar'
	*/
	last(): T | void;

	/**
	* Queue length.
	*
	* @example
	* var FIFO = require( '@stdlib/dstructs/fifo' );
	*
	* var queue = new FIFO();
	*
	* // Examine the initial queue length:
	* var len = queue.length;
	* // returns 0
	*
	* // Add values to the queue:
	* queue.push( 'foo' ).push( 'bar' );
	*
	* // Retrieve the current queue length:
	* len = queue.length;
	* // returns 2
	*/
	readonly length: number;

	/**
	* Removes a value from the queue.
	*
	* @returns removed value
	*
	* @example
	* var FIFO = require( '@stdlib/dstructs/fifo' );
	*
	* var queue = new FIFO();
	*
	* // Add values to the queue:
	* queue.push( 'foo' ).push( 'bar' );
	*
	* // Remove the first value:
	* var v = queue.pop();
	* // returns 'foo'
	*
	* // Add a new value to the queue:
	* queue.push( 'beep' );
	*
	* // Remove the "oldest" queue value:
	* v = queue.pop();
	* // returns 'bar'
	*/
	pop(): T | void;

	/**
	* Adds a value to the queue.
	*
	* @returns queue instance
	*
	* @example
	* var FIFO = require( '@stdlib/dstructs/fifo' );
	*
	* var queue = new FIFO();
	*
	* // Add values to the queue:
	* queue.push( 'foo' ).push( 'bar' );
	*
	* // Remove the first value:
	* var v = queue.pop();
	* // returns 'foo'
	*
	* // Add a new value to the queue:
	* queue.push( 'beep' );
	*
	* // Remove the "oldest" queue value:
	* v = queue.pop();
	* // returns 'bar'
	*/
	push( value: T ): FIFO<T>;

	/**
	* Sets a queue element at a specified index.
	*
	* ## Notes
	*
	* -   If an index argument is not provided, the method sets a value at index `0`.
	*
	* @param value - value to set
	* @param i - element index (default: 0)
	* @throws index argument must be a nonnegative integer
	* @throws index argument is out-of-bounds
	* @throws target queue lacks sufficient storage to accommodate source values
	*
	* @example
	* var FIFO = require( '@stdlib/dstructs/fifo' );
	*
	* var queue = new FIFO();
	*
	* queue.push( 'foo' ).push( 'bar' ).set( 'beep', 0 );
	*
	* var v = queue.get( 0 );
	* // returns 'beep'
	*
	* queue.set( 'boop', 1 );
	*
	* v = queue.get( 1 );
	* // returns 'boop'
	*
	* queue.set( 'beep' );
	*
	* v = queue.get( 0 );
	* // returns 'beep'
	*/
	set( value: T, i?: number ): void;

	/**
	* Returns an array of queue values.
	*
	* @returns queue values
	*
	* @example
	* var FIFO = require( '@stdlib/dstructs/fifo' );
	*
	* var queue = new FIFO();
	*
	* // Add values to the queue:
	* queue.push( 'foo' ).push( 'bar' );
	*
	* // Get an array of queue values:
	* var vals = queue.toArray();
	* // returns [ 'foo', 'bar' ]
	*/
	toArray(): Array<T>;

	/**
	* Serializes a queue as JSON.
	*
	* ## Notes
	*
	* -   `JSON.stringify()` implicitly calls this method when stringifying a `FIFO` instance.
	*
	* @returns serialized queue
	*
	* @example
	* var FIFO = require( '@stdlib/dstructs/fifo' );
	*
	* var queue = new FIFO();
	*
	* // Add values to the queue:
	* queue.push( 'foo' ).push( 'bar' );
	*
	* // Serialize to JSON:
	* var o = queue.toJSON();
	* // returns { 'type': 'fifo', 'data': [ 'foo', 'bar' ] }
	*/
	toJSON(): SerializedFIFO<T>;
}


// EXPORTS //

export = FIFO;
